-- OPTIONAL: records changes made directly in Supabase (table editor, SQL editor) in the admin audit log.
-- Generated by `npm run sql` — do not edit by hand. Needs backend/sql/schema.sql to have been run first.
-- Run it yourself: Supabase dashboard → SQL Editor → New query → paste this file → Run. Safe to run more than once.
-- Changes made by the ReelLingo app itself are skipped here because the app already logs them.

BEGIN;

CREATE OR REPLACE FUNCTION public.reellingo_audit_change() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  changed json := CASE WHEN TG_OP = 'DELETE' THEN row_to_json(OLD) ELSE row_to_json(NEW) END;
BEGIN
  IF current_setting('application_name', true) = 'reellingo-api' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  INSERT INTO public.admin_audit (admin_id, admin_email, action, target, details)
  VALUES (
    'database',
    session_user,
    TG_OP || ' ' || TG_TABLE_NAME,
    COALESCE(changed->>'code', changed->>'key', changed->>'reference', changed->>'user_id', changed->>'billing_id', ''),
    left(json_build_object('before', CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE row_to_json(OLD) END, 'after', CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE row_to_json(NEW) END)::text, 8000)
  );
  RETURN COALESCE(NEW, OLD);
END $$;

REVOKE ALL ON FUNCTION public.reellingo_audit_change() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS reellingo_audit ON public.plans;
CREATE TRIGGER reellingo_audit AFTER INSERT OR UPDATE OR DELETE ON public.plans FOR EACH ROW EXECUTE FUNCTION public.reellingo_audit_change();

DROP TRIGGER IF EXISTS reellingo_audit ON public.app_settings;
CREATE TRIGGER reellingo_audit AFTER INSERT OR UPDATE OR DELETE ON public.app_settings FOR EACH ROW EXECUTE FUNCTION public.reellingo_audit_change();

DROP TRIGGER IF EXISTS reellingo_audit ON public.subscriptions;
CREATE TRIGGER reellingo_audit AFTER INSERT OR UPDATE OR DELETE ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.reellingo_audit_change();

DROP TRIGGER IF EXISTS reellingo_audit ON public.payments;
CREATE TRIGGER reellingo_audit AFTER INSERT OR UPDATE OR DELETE ON public.payments FOR EACH ROW EXECUTE FUNCTION public.reellingo_audit_change();

DROP TRIGGER IF EXISTS reellingo_audit ON public.minute_ledger;
CREATE TRIGGER reellingo_audit AFTER INSERT OR UPDATE OR DELETE ON public.minute_ledger FOR EACH ROW EXECUTE FUNCTION public.reellingo_audit_change();

DROP TRIGGER IF EXISTS reellingo_audit ON public.profiles;
CREATE TRIGGER reellingo_audit AFTER UPDATE OF is_admin, disabled ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.reellingo_audit_change();

COMMIT;
